/* Host-side test of the RG34XX-SP speed-bin xlate. Generated by extracting the function from
 * phase2-mainline/patches/linux/0001-*.patch applied to v7.4-rc2. Build: gcc -Wall -o xt xt.c && ./xt */

#include <stdio.h>
#include <stdint.h>
typedef uint32_t u32;
#define SMCCC_RET_NOT_SUPPORTED -1
struct device_node { int dummy; };
static int g_rev; static u32 g_a, g_b; static int g_aux_ok=1;
static int get_soc_id_revision(void){ return g_rev; }
static int sun50i_read_aux_cell(struct device_node *np, const char *name, u32 *val){
  (void)np; if(!g_aux_ok) return -2; *val = (name[10]=='a')? g_a : g_b; return 0; }
static u32 anbernic_rg34xxsp_efuse_xlate(struct device_node *np, u32 speedbin)
{
	int rev = get_soc_id_revision();
	u32 aux_a, aux_b;

	switch (speedbin & 0xffff) {
	case 0x2400:
	case 0x5000:
	case 0x5400:
	case 0x7400:
		return 0;
	case 0x2c00:
		return 1;
	case 0x2000:
	case 0x2800:
		return 2;
	case 0x6c00:
	case 0x7c00:
		if (rev == SMCCC_RET_NOT_SUPPORTED)
			return 3;
		return (rev & 0x7) == 0 ? 4 : 5;
	case 0x5c00:
		if (rev == SMCCC_RET_NOT_SUPPORTED)
			return 3;
		if ((rev & 0x7) == 0)
			return 6;
		if (sun50i_read_aux_cell(np, "speed-aux-a", &aux_a) ||
		    sun50i_read_aux_cell(np, "speed-aux-b", &aux_b))
			return 8;
		aux_a = (aux_a & 0xff) << 5;
		aux_b &= 0x3ff;
		if (aux_b - 0x26 <= 7 && aux_a - 0xa60 <= 0x940)
			return 7;
		return 8;
	default:
		return 3;
	}
}


int main(void){
  struct device_node n; int fails=0;
  struct { u32 f; int rev; u32 a,b; int ok; int want; } t[] = {
   {0x2400,1,0,0,1,0},{0x5000,0,0,0,1,0},{0x5400,3,0,0,1,0},{0x7400,1,0,0,1,0},
   {0x2c00,1,0,0,1,1},{0x2000,1,0,0,1,2},{0x2800,0,0,0,1,2},
   {0x6c00,0,0,0,1,4},{0x6c00,1,0,0,1,5},{0x7c00,0,0,0,1,4},{0x7c00,2,0,0,1,5},
   {0x6c00,-1,0,0,1,3},{0x5c00,-1,0,0,1,3},{0x5c00,0,0,0,1,6},
   {0x5c00,1,0x53,0x26,1,7},  /* a=0x53<<5=0xa60, b=0x26: low edges -> c1 */
   {0x5c00,1,0x9d,0x2d,1,7},  /* a=0x9d<<5=0x13a0, b=0x2d: high edges -> c1 */
   {0x5c00,1,0x52,0x26,1,8},  /* a below range -> c2 */
   {0x5c00,1,0x9e,0x26,1,8},  /* a above range -> c2 */
   {0x5c00,1,0x60,0x25,1,8},  /* b below range -> c2 */
   {0x5c00,1,0x60,0x2e,1,8},  /* b above range -> c2 */
   {0x5c00,1,0x60,0x30,0,8},  /* aux cells missing -> c2 */
   {0x5c00,9,0x60,0x26,1,7},  /* rev&7 = 1 -> rev-dependent path */
   {0x5c00,8,0x60,0x26,1,6},  /* rev&7 = 0 -> c0 */
   {0x1234,1,0,0,1,3},{0x0000,1,0,0,1,3},{0x5d00,1,0,0,1,3},{0x6000,1,0,0,1,3},
   {0x12400,1,0,0,1,0},       /* upper bits ignored */
  };
  for (unsigned i=0;i<sizeof t/sizeof t[0];i++){
    g_rev=t[i].rev; g_a=t[i].a; g_b=t[i].b; g_aux_ok=t[i].ok;
    u32 r=anbernic_rg34xxsp_efuse_xlate(&n,t[i].f);
    if((int)r!=t[i].want){ printf("FAIL fuse=0x%x rev=%d got %u want %d\n",t[i].f,t[i].rev,r,t[i].want); fails++; }
  }
  printf("%u cases, %d failures\n",(unsigned)(sizeof t/sizeof t[0]),fails); return fails!=0;
}
